import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';

const FAKE_ASSETS_By_ID = {
  // populated by fakeImage()/fakePage() calls
};

function fakeImage({ id, name, url, alt }) {
  const asset = {
    id: String(id),
    type: 'image',
    name,
    alt,
    url,
    urls: [url],
    imageVariations: {
      original: { url, width: 900, height: 700 },
    },
  };
  FAKE_ASSETS_By_ID[String(id)] = asset;
  return asset;
}

function fakePage({ id, name, url }) {
  const asset = { id: String(id), type: 'pageStandard', name, url };
  FAKE_ASSETS_By_ID[String(id)] = asset;
  return asset;
}

fakeImage({
  id: 5001,
  name: 'Placeholder image',
  url: 'https://picsum.photos/id/1039/900/700',
  alt: 'Placeholder image',
});
fakePage({
  id: 5002,
  name: 'Sample page title',
  url: 'https://example.com/sample-page',
});

/**
 * This component resolves `image`/`linkAsset` at render time via
 * info.fns.resolveUri(uri) -- confirmed (via the same mechanism proven
 * against a real live Squiz DXP backend for `card`) to wrap its result in a
 * { ok, data } envelope. This Storybook fake is a separate,
 * project-controlled mock that exists purely so the resolution *logic* in
 * main.js can be verified here without a real Matrix backend.
 */
const mockInfo = squizInfoMock({
  mock: {
    resolveUri(uri) {
      const assetId = /^matrix-asset:\/\/[a-zA-Z0-9.-]+\/(\d+)/.exec(String(uri ?? ''))?.[1];
      return { ok: true, data: FAKE_ASSETS_By_ID[assetId] ?? null };
    },
  },
});

/**
 * "Show code" can't dynamically capture our output: the shared
 * squizStoryRenderer wraps it in lit's until() because main() is async
 * (per the DXP edge contract), but Storybook's web-components source
 * decorator reads the rendered container's innerHTML synchronously, before
 * that promise resolves -- so dynamic capture always sees an empty result.
 * Precomputing the real HTML here and handing it to Storybook explicitly
 * is the only reliable way to show it.
 */
const squiz = squizStoryRenderer(comp.main);

const BODY_HTML = '<p>Lorem ipsum dolor sit amet, consectetur adipiscing elit. Nam ac nunc neque. Praesent posuere lobortis purus, ac laoreet est volutpat in.</p><p>Nulla facilisi. Vestibulum ante ipsum primis in faucibus orci luctus et ultrices posuere cubilia curae.</p>';

export default {
  title: 'dxp components/Featured Content',
  parameters: {
    layout: 'padded',
  },
};

const defaultArgs = {
  image: 'matrix-asset://ntg/5001',
  imagePosition: 'Right',
  background: 'White',
  border: true,
  linkAsset: 'matrix-asset://ntg/5002',
  body: BODY_HTML,
};
const defaultHtml = await squiz.markup(defaultArgs, mockInfo);

export const Default = {
  render: (args) => squiz(args, mockInfo),
  args: defaultArgs,
  argTypes: {
    image: {
      control: 'text',
      description: 'matrix-asset-uri. Only matrix-asset://ntg/5001 resolves in this Storybook preview (mocked).',
    },
    imagePosition: { control: 'radio', options: ['Left', 'Right'] },
    background: { control: 'radio', options: ['White', 'Gray'] },
    border: { control: 'boolean' },
    linkAsset: {
      control: 'text',
      description: 'matrix-asset-uri. Only matrix-asset://ntg/5002 resolves in this Storybook preview (mocked). Its name becomes the H2 heading and its url becomes the "Read more" link.',
    },
    body: { control: 'text', description: 'Raw HTML (FormattedText).' },
  },
  parameters: {
    docs: { source: { code: defaultHtml, language: 'html', type: 'code' } },
  },
};

const imageLeftArgs = { ...defaultArgs, imagePosition: 'Left' };
const imageLeftHtml = await squiz.markup(imageLeftArgs, mockInfo);

export const ImageLeft = {
  render: () => squiz(imageLeftArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'imagePosition is "Left" -- image and text swap sides.' },
      source: { code: imageLeftHtml, language: 'html', type: 'code' },
    },
  },
};

const grayBackgroundArgs = { ...defaultArgs, background: 'Gray' };
const grayBackgroundHtml = await squiz.markup(grayBackgroundArgs, mockInfo);

export const GrayBackground = {
  render: () => squiz(grayBackgroundArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'background is "Gray".' },
      source: { code: grayBackgroundHtml, language: 'html', type: 'code' },
    },
  },
};

const noBorderArgs = { ...defaultArgs, border: false };
const noBorderHtml = await squiz.markup(noBorderArgs, mockInfo);

export const NoBorder = {
  render: () => squiz(noBorderArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'border is false -- no border around the card.' },
      source: { code: noBorderHtml, language: 'html', type: 'code' },
    },
  },
};

const unresolvableArgs = {
  image: 'matrix-asset://ntg/9999999',
  linkAsset: 'matrix-asset://ntg/9999998',
  body: BODY_HTML,
};
const unresolvableHtml = await squiz.markup(unresolvableArgs, mockInfo);

export const Unresolvable = {
  render: () => squiz(unresolvableArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'Neither image nor linkAsset resolve -- no image, no heading, no "Read more" link, but body text still renders.' },
      source: { code: unresolvableHtml, language: 'html', type: 'code' },
    },
  },
};
